fn list_deep_clone(arr: &Vec<u64>) -> Vec<u64> {
    // Preallocate a new Vec with the same length as the input
    let mut copied = Vec::with_capacity(arr.len());
    // Copy each element by value into the new Vec
    for &value in arr.iter() {
        copied.push(value);
    }
    copied
}

